quests[89381] = { id = 89381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nadelkissen", description = "Oooh! Ganz schön mutig von Euch, während unseres Trainings auf dem Schießplatz herumzulaufen. Ihr fordert es ja geradezu heraus, ein Geschoss ins Knie zu bekommen, oder vielleicht ins Hinterteil, so wie Ihr hier herumtanzt.\n\nAber Eure Sicherheit ist Eure Sache. Da Ihr offenbar das Risiko sucht, wollt Ihr uns vielleicht zur Hand gehen? Das Aufsammeln der Pfeile nach jeder Runde kostet viel wertvolle Übungszeit.\n\nWir wäre es, wenn Ihr ein paar für mich einsammelt?", sourceObjective = "Sammelt Pfeile auf dem Schießplatz südlich vom Stadtplatz von Neu-Avalon. Ihr könnt auch Pfeile im Kampf mit Waldläufern erbeuten.", sourceObjectiveStatus = "unverified-source-field" }
quests[89421] = { id = 89421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kugelhimmel", description = "Ihr denkt vielleicht: \"Aber was, wenn ich lieber einen Munitionsbeutel hätte\", oder \"wenn ich etwas sage, wird sie mich dann auch in einen Kugelhagel stellen?\" Ich kann zwar nicht Eure Gedanken lesen, aber ein guter Waldläufer muss vorausschauend denken.\n\nDie Wahrheit ist, dass wir hier keine Kugeln verschießen, obwohl ich mich stets dafür ausspreche. Aber falls, sagen wir, ein Haufen Patronen vor meinen Füßen erscheinen würde, hätte ich wohl keine andere Wahl, als einen angemessenen Beutel für deren Aufbewahrung zu entwerfen.\n\nWenn doch nur...", sourceObjective = "Stellt Thoriumpatronen her oder kauft welche von einem Spielercharakter mit Ingenieursberuf, und bringt sie zu Kyndra Swiftarrow beim Schießplatz von Neu-Avalon.", sourceObjectiveStatus = "unverified-source-field" }
quests[89445] = { id = 89445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klingen des Lichts", description = "Selbst zerstört und zerbrochen erkennt Ihr, dass Ihr ein wahrhaft beeindruckendes Schwert vor Euch habt. Wenn Ihr das Material versteht, aus dem diese Klinge geschmiedet wurde, könntet Ihr möglicherweise eine wahrhaft einzigartige Waffe daraus herstellen. Doch erst müsst Ihr einen fähigen Schmied finden, der seine Eigenschaften bestimmen und einen Weg finden kann, das Material zu bearbeiten.", sourceObjective = "Findet einen Schmied, der Euch mehr über die zerstörte lichtgeschmiedete Klinge sagen kann.", progress = "Wie? Ich habe keine Zeit, mit Euch zu plaudern! Diese Brustpanzer hämmern sich nicht von selbst!", completion = "Oooh! Das ist aber mal ein beeindruckendes Schwert, das Ihr da habt!\n\nIhr sucht nach jemandem, der dieses Material bearbeiten kann? Hm, nun, ich sage es nur ungern, aber die Geheimnisse dieses Materials zu lüften, übersteigt vermutlich meine Fähigkeiten. Wenn nur Omarion hier wäre. Er war der hiesige Handwerksmeister und absoluter Experte in Sachen exotische Materialien und Legierungen. Er wäre perfekt für sowas. Das einzige Problem ist, dass er verschwunden ist!\n\nSollte er noch am Leben sein, wäre er Eure beste Adresse!", sourceObjectiveStatus = "unverified-source-field" }
quests[89446] = { id = 89446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verschwundene Handwerker", description = "<Handwerker Wilhem scheint Euch nicht helfen zu können, aber er empfahl Euch seinen früheren Meister, einen Mann namens Omarion. Solltet Ihr ihn finden, könnte er vielleicht mehr über dieses Material wissen.>", sourceObjective = "Findet Meisterhandwerker Omarion", progress = "<Omarion starrt ausdruckslos an Euch vorbei.>", completion = "Ich verstehe. Niemand sucht nach mir, außer sie brauchen etwas. Schon gut, schon gut. Ich muss ohnehin nicht gerettet werden. Ich sterbe gerne genau hier, an diesem lichtverlassenen Ort. Lasst mich einfach hier zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[89447] = { id = 89447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extravaganter Geschmack", description = "Ihr habt also ein ziemlich ungewöhnliches Stück Metall. Wen interessiert's?\n\nOh, ich soll Euch mehr darüber erzählen? Nun, es ist ein Schwert, und es ist kaputt. War es das jetzt?\n\n<Omarion starrt Euch finster an, dann seufzt er tief, als Ihr keine Anstalten macht, zu gehen.>\n\nNa gut. Lasst das Schwert hier, dann sehe ich es mir an. Während ich das tue, könnte ich vielleicht etwas zu Essen vertragen. Ich kannte einst einen Goblin, Dirge Quikcleave. Er macht die besten Chimaerokkoteletts. Bringt mir einige.", sourceObjective = "Bringt Meisterhandwerker Omarion in Naxxramas zehn Portionen \"Dirges abgefahrene Chimaerokkoteletts\".", progress = "Wie sich herausstellt, ist es nicht gerade eine Priorität untoter Entführer, einen zu ernähren. Nicht, dass es mich kümmern würde. Ich wäre hier gut und gerne verhungert, aber da Ihr mich nicht in Frieden lassen wollt, könntet Ihr mir wenigstens eine ordentliche Henkersmahlzeit bringen.", completion = "Das war genau das Richtige, {class}.\n\nAlso, zu dem Schwert. Es ist... tatsächlich sehr eindrucksvoll. Es strahlt Hitze aus, die Schneide behält ihre Schärfe beinahe übernatürlich gut, und sie scheint die Untoten abzuschrecken, was man daran sieht, dass kein einziger Zombie mehr vorbei kam und versucht hat, mich zu essen, seit Ihr mich damit allein gelassen habt.\n\nZu schade, wirklich. Zombies sind nicht die besten Gesprächspartner, aber an einem Ort wie diesem nimmt man, was man kriegen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[89448] = { id = 89448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sammeln des Lichts", description = "<Omarion wirkt erheblich lebendiger als bei Eurer ersten Begegnung mit ihm.>\n\nAlso gut, {class}, Ihr habt mein Interesse geweckt. Dieses Metall ist absolut einzigartig und ich würde gerne weiter damit experimentieren. Aber dafür brauche ich weitere Proben des Rohmaterials. Bringt mir etwa ein Dutzend Barren von diesem \"lichtgeschmiedeten\" Eisen und versucht, mehr darüber herauszufinden, wo diese Waffen hergestellt werden. Ein Schmied ist immerhin nur so gut wie sein Werkzeug und seine Werkstatt.", sourceObjective = "Bringt zwölf Barren lichtgeschmiedetes Eisen zu Meisterhandwerker Omarion in Naxxramas und deckt auf, wo der Scharlachrote Kreuzzug diese neuen Waffen herstellt.", progress = "Ich wünschte, ich hätte etwas Kaja'Cola zu diesen Koteletts. Oh, Ihr habt noch nie von Kaja'Cola gehört? Solltet Ihr je die Gelegenheit haben, welche zu probieren, wird das Euer Leben verändern.", completion = "Die sollten genügen. Was habt Ihr noch auf Eurem Ausflug erfahren?\n\n<Ihr erzählt Omarion von der Strahlenden Schmiede, die Ihr in der Scharlachroten Enklave gefunden habt.>\n\nSehr interessant, es gibt also einen lichterfüllten Amboss in der Scharlachroten Enklave, wo sie diese Waffen herstellen?\n\nNun, dann führt nichts daran vorbei. Ich werde mir diese Schmiede persönlich ansehen müssen. Ich werde wohl davon absehen müssen, an diesem grässlichen Ort zu sterben.", sourceObjectiveStatus = "unverified-source-field" }
quests[89463] = { id = 89463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschwiegenheitserklärung", description = "Ich bin kein solcher Goblin, der seine Geheimnisse mit irgendwelchen dahergelaufenen Abenteurern teilen. Aber ich BIN einer, der die Geheimnisse eines Gnoms teilt! Zufälligerweise konnte ich auf meinem Weg hierher einige Baupläne in die Finger bekommen und ich arbeite daran, die Mängel in den Entwürfen auszuarbeiten. Sie nutzen immer noch Sicherheitslunten! Könnt Ihr das fassen? SICHERHEITSLUNTEN!\n\nWie dem auch sei, ich teile meine Fortschritte gerne mit Euch, aber ich brauche eine Schreibfeder, wenn ich den ganzen Kram aufschreiben soll. Und ich könnte ein gemütliches Fleckchen brauchen, an dem ich in Ruhe nachdenken kann. Was sagt Ihr dazu?", sourceObjective = "Zischlunte in Neu-Avalon hat nach einer Schreibfeder und etwas, das sein Versteck gemütlicher macht, gebeten. Eine schicke Schreibfeder kann im Rathaus von Neu-Avalon gefunden werden, und in der Nähe von Scholomance oder den Karazhangruften könnt Ihr ein Requisitenhaus finden.", progress = "Ah, Ihr seid es! Ich bin schon gespannt, was Ihr mir gebracht habt.", completion = "Wisst Ihr, ich weiß nicht ganz, was ich erwartet habe, aber gewiss nicht... das. Ich schätze, es passt zu den Bäumen. Ich sollte mich nicht beschweren, hauptsächlich, weil ich am Schluss anfangen würde zu schreien, und das will keiner von uns beiden.\n\nViel wichtiger ist die Feder! Ich habe vergessen zu erwähnen, dass mir die Tinte ausgegangen ist, aber ein wenig Motoröl sollte da Wunder wirken.\n\n<Zischlunte prüft die Tauglichkeit der Feder mit einem grob skizzierten Bauplan.>\n\nSo, bitte sehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[89471] = { id = 89471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin-Tüftelei", description = "Ich würde sagen, unsere Geschäftsbeziehung ist inzwischen fest etabliert. Ich hab den Grips, Ihr habt die Muckis. Das ist großartig, weil ich vor dreißig Sekunden gemerkt habe, dass mir einige wichtige Teile fehlen!\n\nHier habt Ihr eine Liste von Dingen, die ich diesen Plänen zufolge brauche, abgesehen von dem ganzen Gnomenschrott. Bis dahin kümmere ich mich darum, diese Pläne zu überarbeiten. Sobald Ihr zurück seid, können wir loslegen!", sourceObjective = "Zischlunte in Neu-Avalon hat Euch eine Einkaufsliste mit technischen Teilen für seine Erfindungen gegeben. Besorgt diese und bringt sie zu ihm.", progress = "Ihr habt Euch Zeit gelassen, ich dachte schon, dieser Scharlachrote Kreuzzug hätte Euch erwischt. Habt Ihr alles, worum ich gebeten habe?", completion = "Ich hätte wissen sollen, dass Ihr meine Einkaufsliste auf eine geschickte Weise ignoriert. Wie soll ein Goblin hierzulande etwas zwischen die Zähne bekommen? Egal.\n\nIhr freut Euch sicher zu hören, dass ich den Bauplan für meine neueste Erfindung fertiggestellt habe: Die Tüftlerkiste! Dieses Gerät an sich ist unscheinbar, aber das ist ja der Sinn der Sache! Ihr müsst nur einige sorgfältig kalibrierte Teile in die hintere Schalttafel einsetzen und dann, wenn Ihr bereit seid, drückt Ihr auf den großen, roten Knopf!\n\nWas dann passiert? Das findet Ihr am besten selbst heraus!", sourceObjectiveStatus = "unverified-source-field" }
quests[89485] = { id = 89485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Launische Schrecken", description = "So sehr mir der Gedanke auch gefällt, Euch als Versuchsobjekt für meine Erfindungen zu nutzen, bin ich mir bei dieser nicht ganz sicher. Sie sollte Euch eigentlich einige Meter nach vorn teleportieren, aber als ich den ersten Prototyp mit einem Stock gepikst hatte, ist er einfach verschwunden und hat den Stock mitgenommen!\n\nIch habe seitdem einige Anpassungen an mehreren Geräten gemacht. Ich habe gesehen, wie Ihr Euch unter die Einheimischen hier gemischt habt. Vielleicht könnt Ihr sie ja dazu überreden, ihn auszuprobieren. Und wenn Ihr Euch dann mutig genug fühlt, testet ihn gerne selbst.", sourceObjective = "Schleicht Euch verkleidet an Bürger von Neu-Avalon an und gebt ihnen einen Portiporter. Sobald Ihr Euch davon überzeugt habt, dass es nicht zum sofortigen Tod führt, nutzt das Gerät selbst, um das Problem zu identifizieren, von dem Zischlunte gesprochen hat.", completion = "Wie... bitte?! Könnt Ihr das wiederholen?\n\n<Zischluntes Augen werden trüb, nicht vor Schrecken, sondern vor Langeweile.>\n\nIhr sagt also, das Gerät funktioniert, es wird nur irgendwie gestört? Warum bin ich da nicht selbst drauf gekommen! Das ergibt total Sinn. Ich habe keine Ahnung, wie es zu reparieren ist, aber es ergibt Sinn.\n\nHier ist der Bauplan, bastelt ruhig daran herum. Ich bin sicher, er beschreibt schon fast das großartigste Kurzstrecken-Transportgerät aller Zeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[89486] = { id = 89486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Prise Schießpulver", description = "Ich bin sicher, Ihr wollt dringend wissen, was ich mit dem Schießpulver vorhabe.\n\nHabt Ihr je von Nitroboostern gehört? Nicht Nitropuster. Sondern Booster. Wenn Ihr ja sagt, seid Ihr ein Lügner, weil sie noch nicht erfunden wurden. Bis jetzt!\n\nIch möchte Euch die Ehre erweisen, sie auszutesten. Ihr müsst nur hier ein wenig Schießpulver reintun und den Knopf drücken. Wenn Ihr noch schneller sein wollt, nehmt mehr Schießpulver!\n\nTestet sie auf jeden Fall auf unterschiedlichem Untergrund, bevor Ihr zurückkommt.", sourceObjective = "Erreicht die folgenden Orte in Neu-Avalon innerhalb des Zeitlimits.", completion = "Schön! Ihr habt es bis auf einige Verbrennungen unversehrt zurückgeschafft. Ich glaube, wir sind uns einig, dass dieser Testlauf ein voller Erfolg war. Ich würde sogar sagen, wir können das mit mehr Schießpulver noch verbessern!\n\nDanke für die Daten. Ich wusste, Ihr enttäuscht mich nicht. Hier ist der Plan für Eure ganz eigenen Nitrobooster. Ich bestehe darauf, dass Ihr Euren Schießpulververbrauch niedrig haltet. Sonst bekomme ich noch Konkurrenz.", sourceObjectiveStatus = "unverified-source-field" }
quests[89487] = { id = 89487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viel Lärm um Magneten", description = "Sogar mit den Vorräten, die Ihr gesammelt habt, kann ich ohne meine Werkstatt nicht viel ausrichten. Ich habe einen Plan ausgeheckt, einen genialen noch dazu, wie wir endlich die Funktionsweise dieser seltsamen Magnetfelder verstehen können. Ich vermute, dass ich mit genug präziser Gobliningenieurskunst eine Methode entwickeln kann, den Abstand zwischen zwei Personen auf ein permanentes Minimum zu reduzieren! Niemand wird mich je wieder ohne ein Geschäft stehen lassen.\n\nUm meine Theorie zu testen, nehmt diesen Prototyp und wedelt ein wenig in Neu-Avalon damit herum. Mit ein wenig Glück findet Ihr vielleicht etwas!", sourceObjective = "Nutzt den Magnetprototyp in Neu-Avalon, um magnetische Teile zu entdecken und anzuziehen. Wenn Ihr Zischluntes Theorie ausreichend bewiesen habt, kehrt zu ihm zurück.", progress = "Wisst Ihr, es ist erfrischend, an etwas zu arbeiten, das mich nicht mit einer signifikanten Chance in ein Häufchen Asche verwandelt. Vielleicht sind die Gnome da doch etwas auf der Spur.", completion = "Es hat funktioniert!? Ich meine, es hat funktioniert! Natürlich hat es das... Uff, ich sollte lernen, immer auf meinen Bauch zu vertrauen.\n\nIhr habt so lange gebraucht, dass ich schon dachte, meine Theorie wäre falsch. Anstatt das Gerät auf die Nutzung gegensätzlicher Polaritäten zu kalibrieren, ist es darauf ausgelegt, einen Energieschub derselben Polarität auszustoßen.\n\nAber zurück ans Zeichenbrett. Hier ist der Plan, falls es zu Eurer Geschäftsstrategie passt, die Leute abzustoßen.", sourceObjectiveStatus = "unverified-source-field" }
quests[89489] = { id = 89489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erhöhte Beuterate", description = "Jetzt, da wir wissen, dass meine Erfindungen als eigenständige Geräte funktionieren, ist der nächste logische Innovationsschritt, ihre Wiederverwendbarkeit und Lebensdauer zu verbessern! Ich glaube, dass keiner von uns jedes Mal eine ganze Handvoll Gold wegwerfen will, nur um sich über eine Pfütze zu teleportieren.\n\nIch habe wie immer eine Idee.\n\nGürtel sind ein leidig unterschätzter Ausrüstungsgegenstand und dazu auch noch leicht zu erreichen. Es ergibt Sinn, sie durch wiederverwendbare Geräte zu verbessern, aber erst brauche ich einige Testexemplare. Geht und stehlt ein paar für mich.", sourceObjective = "Zischlunte in Neu-Avalon verlangt nach vielen Gürteln, und das aus gutem Grund. Die Soldaten von Neu-Avalon könnten eine gute Beschaffungsquelle sein.", progress = "Ich bin bereit loszutüfteln, sobald Ihr mir ein paar Gürtel bringt.\n\nWas? Nein, mein eigener kommt nicht in Frage!", completion = "Während Ihr fort wart, konnte ich ALLE DREI Baupläne für die Gürteltüfteleien fertigstellen! Das ist einerseits sehr beeindruckend, was mich angeht, aber andererseits ziemlich beschämend für Euch.\n\nMir ist auch klar geworden, dass wir bislang ziemliches Glück hatten, dass unser Chaos nicht mehr Aufmerksamkeit von diesen lästigen Menschen auf sich gezogen hat. Jetzt bin ich mir nicht mehr sicher, ob ich diese Gürtel überhaupt noch brauchen werde, da ich mich von nun an ganz auf meine Flucht konzentrieren werde. Aber ich nehme sie trotzdem, um damit eine Sammlung anzufangen. Wer weiß, wozu sie noch gut sein werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[89491] = { id = 89491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein komplizierter Fluchtplan", description = "Nun, das hat Spaß gemacht, aber ich glaube, dass unsere Anwesenheit hier nicht mehr erwünscht ist. Ich wollte im Notfall meine neuen Geräte nutzen, um mich aus dem Staub zu machen, aber ich kann nicht mein ganzes neues Zeug auf einmal tragen!\n\nWie Ihr gesehen habt, konnte ich hier nach meiner Ankunft eine Transporterplattform einrichten. Sie muss nur ein wenig kalibriert werden.\n\nNehmt dieses Gerät und verwendet es in der Nähe der Tore, des Bogenschießplatzes und innerhalb des Gasthauses. Dann und nur dann könnt Ihr Euch auf meinen Teleporter stellen und Euren Teleporter nach Gadgetzan oder Everlook nutzen, um ihn anzuwerfen.", sourceObjective = "Benutzt das Triangulationssamophlang an drei unpraktischen Orten und verwendet dann Euren extrem sicheren Transporter: Gadgetzan oder Euren Dimensionszerfetzer - Everlook, während Ihr auf der Teleportationsplattform steht, um die Kalibrierung abzuschließen. Kehrt dann zu Zischlunte in Neu-Avalon zurück.", completion = "Ihr seid in einem Stück zurück und der Teleporter schnurrt wie ein Orc! Ein Zeugnis wahrer goblinscher Brillanz.\n\nÜbrigens... also ähm... ich war so aufgeregt, den Teleporter zum Laufen zu bringen, dass ich vergessen habe, Euch den Bauplan für eine einfache Rückreise zu geben, als Ihr gegangen seid. Ihr nehmt mir das nicht übel, oder?\n\nWie dem auch sei, jetzt müsst Ihr nur noch Euer eigenes Modul zusammenbauen, um die Rückreisefunktion zu nutzen. Ich selbst gehe zurück, sobald ich meine Sachen gepackt habe. In der Zwischenzeit könnt Ihr jederzeit zu mir kommen, wenn Ihr Teile braucht.\n\nDanke für all Eure Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[89562] = { id = 89562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mein alter Feind", description = "Ich hatte gehört, Caldoran wäre in Naxxramas, und befürchtet, dass ich an seiner Seite an die Front gezwungen werden würde, falls die Schlacht eine ungünstige Wendung nehmen sollte.\n\nDie Argentumdämmerung unterstützt zwar Eure Hilfe für die Streitkräfte der Scharlachroten Rückeroberung, aber ich muss Euch dennoch eindringlich warnen: Nehmt Euch vor Baelin Caldoran in Acht. Meine Hände zittern vor Zorn, allein wenn ich daran denke, welche Gräueltaten dieser Mann an den Unschuldigen verübt hat. Ihr dürft ihm NICHT trauen. Bitte, ich flehe Euch an, hört auf meine Worte.", sourceObjective = "Erfahrt mehr über Baelin Caldoran von Leonid Barthalomew dem Geachteten.", completion = "Das ist alles, was ich im Moment zu dieser Angelegenheit sagen kann. Ich habe Jahre gebraucht, um aus dem dunklen Loch im Inneren meiner Seele hervorzukriechen, nachdem dieser Mann mit mir fertig war.\n\nIm Moment mögen wir vorläufige Verbündete sein, aber ich werde dafür sorgen, dass Caldoran für seine Verbrechen bezahlt... eines Tages. Dieser Schwur bleibt ungebrochen. In der Zwischenzeit seid extrem vorsichtig in Eurem Umgang mit ihm.", sourceObjectiveStatus = "unverified-source-field" }
quests[89563] = { id = 89563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leonids Bürde", description = "Ich habe zufällig Euer Gespräch mit Leonid über Inquisitor Caldoran belauscht. Die wenigen Einzelheiten, die Leonid Euch mitgeteilt hat, sind nur ein mickriger Fetzen der Geschichte, die diese beiden verbindet. Dazu zählt auch das Leid, das Caldoran ihm zugefügt hat. Ich war da, als Leonid an seinem absoluten Tiefpunkt war, und habe ihm geholfen, die Stärke zu finden, sich wieder aufzuraffen.\n\nIch fürchte mich davor, was unsere fortlaufende Zusammenarbeit mit dem Scharlachroten Kreuzzug in Leonid anrichten wird, vor allem wenn er dadurch diesem Mann näherkommen wird.", sourceObjective = "Erhaltet Anweisungen von Lord Maxwell Tyrosus.", completion = "Ich behalte die Dinge hier in meinem noch funktionierenden Auge, und Ihr solltet Caldoran nicht aus dem Blick lassen, während Ihr mit den Rückeroberungstruppen zusammenarbeitet. Ich traue keinem unserer \"Verbündeten\", und ich vertraue ihm am wenigsten.\n\nSprecht auch noch einmal mit Leonid. Ich habe ihn um eine Mission gebeten, und es wäre gut, wenn Ihr ihn begleiten könntet. Ich denke, ein wenig Ablenkung von diesem Ort könnte ihm guttun.", sourceObjectiveStatus = "unverified-source-field" }
quests[89567] = { id = 89567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verunglückte Karawane", description = "Lord Tyrosus hat mich gebeten, die Karawanenüberreste des Scharlachroten Kreuzzugs im Pestwald entlang der Straße nach Stratholme zu untersuchen.\n\nJüngsten Berichten zufolge gab es kurz vor dem Schisma in Tyrs Hand großflächige Bewegungen des Kreuzzugs in den gesamten Pestländern. Diese Karawane könnte Hinweise auf ihren Zweck bergen.\n\nUntersucht vor meiner Ankunft die Karawane und versucht herauszufinden, welchen Zweck sie hatte. Ich treffe Euch dort und wir werden das gemeinsam untersuchen.", sourceObjective = "Untersucht Karawanenüberreste des Scharlachroten Kreuzzugs im Pestwald entlang der Straße nach Stratholme und sprecht dort mit Leonid Barthalomew dem Geachteten, wenn Ihr mehr herausgefunden habt.", progress = "An dieser Sache ist definitiv etwas merkwürdig. Konntet Ihr etwas Interessantes in Erfahrung bringen?", completion = "Diese Karawane transportierte also... Seuchenproben aus Naxxramas? Aber warum? Zu welchem Zweck? Wollte der Scharlachrote Kreuzzug die Seuche studieren, um sie zu bekämpfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[89568] = { id = 89568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas Neues", description = "Ich denke, wir müssen mehr über diese neue Seuche erfahren. Sie scheint darauf abzuzielen... Untote und Lebende zu töten? Die Untoten haben eine natürliche Immunität gegen die Seuche des Untodes, zumal sie ihr Ergebnis sind. Aber wenn meine Vermutung stimmt, könnte das hier etwas Neues und Furchtbares sein.\n\nIch verabscheue es, die Untoten hier noch mehr zu quälen, aber wir müssen mehr erfahren, bevor wir zur Kapelle des hoffnungsvollen Lichts zurückkehren.", sourceObjective = "Setzt die neuen Seuchenproben gegen geschwächte Menschenfresserghule, Stichelnarbenschrecken, verfluchte Magier sowie Soldaten und Wärter der Geißel im Pestwald ein und beobachtet ihre Wirkung.", progress = "So nahe an Stratholme zu sein, gibt mir ein ungutes Gefühl. Nach allem...\n\n<Leonid Barthalomew der Geachtete hält kurz inne und blickt in Richtung Stratholme. Ihr bemerkt, dass seine Hand leicht zittert.>\n\nVergesst es. Es ist nichts.\n\nLasst uns schnell unsere Angelegenheiten hier erledigen, {name}.", completion = "Die Wirkung dieser Seuchenproben auf die Untoten ist stark und beängstigend. Wenn sie gegen die Verlassenen in den Ruinen von Lordaeron eingesetzt werden würden, könnte das katastrophale Folgen haben.\n\nEs gibt noch einen weiteren Test, den wir durchführen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[89574] = { id = 89574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diener des Todes", description = "Für mich gibt es nichts Verachtenswerteres als die lebenden Agenten des Lichkönigs. Ich verabscheue und verurteile alle, die Recht von Unrecht unterscheiden können und dennoch freien Willens beschließen, dem Tod zu dienen. Nehmt noch einmal die Seuchenproben und testet sie an den lebenden Mitgliedern des Kults der Verdammten in der Nähe.\n\nHabt kein Mitleid mit diesen Monstern und zeigt ihnen kein Erbarmen. Sie haben sich auf die Seite der Verdammnis gestellt, und verdammt sollen sie sein.", sourceObjective = "Setzt die neuen Seuchenproben gegen die dunklen Beschwörer und Totenbeschwörer in den Östlichen Pestländern ein und beobachtet ihre Wirkung.", progress = "Ich habe diese Forschungsnotizen studiert, und was ich sehe, ist furchterregend.\n\nDer Scharlachrote Kreuzzug hat diese Seuche entwickelt.", completion = "Es ist genau, wie ich vermutet hatte. Diese Seuche hat eine ähnliche Wirkung auf die Lebenden wie auch auf die Toten. Ich befürchte, das verspricht nichts Gutes. Für niemanden.\n\nDie Frage, die sich mir stellt, ist, wie ist es den Scharlachroten Kreuzzüglern gelungen, so eine Seuche zu entwickeln? Sie müssten dazu ein tiefes Verständnis der ursprünglichen Seuche des Untodes haben, und die Forschung an solchen Seuchen ist für die Lebenden... schwierig. Das ist überaus besorgniserregend.\n\nIch nehme an, wir haben hier alles erfahren, was wir konnten. Doch bevor wir zurückkehren... könnte ich Euch um einen Gefallen bitten?", sourceObjectiveStatus = "unverified-source-field" }
quests[90107] = { id = 90107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die neu geformte Klinge", description = "Ich denke, ich bin mit der Legierung jetzt so weit, dass wir sie zuverlässig für die Herstellung des Klingenrohlings benutzen können. Zum Glück sollten wir mit allem, was Ihr für mich gesammelt habt, reichlich Rohmaterialien dafür haben.\n\nTretet bitte einen Schritt zurück. Die Arbeit in der Schmiede kann... dramatisch sein.", sourceObjective = "Tretet etwas zurück, während Meisterhandwerker Omarion versucht, die neugeschmiedete Klinge des Aschenbringers herzustellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[90116] = { id = 90116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilige Fäden", description = "Dieser Webstuhl ist etwas Besonderes. Wusstet Ihr das? Alle Werkzeuge unserer Handwerker werden von unseren Hohepriestern gesegnet. \n\nBesonders der Webstuhl zieht abtrünnige Stoffe und Fäden an, die für die Verarbeitung zu den heiligsten unserer Zeremoniengewändern bestimmt sind. Mit genügend Zeit sammeln wir genügend davon, um eine neue Robe herzustellen und solche Tage sind Grund zum Feiern, zumindest für mich.\n\nWenn Ihr aus eigener Neugier an dem Prozess interessiert seid, webt einige Stoffballen in der Nähe des Webstuhls und seht, wie das Licht die Arbeit voranführt.", sourceObjective = "Erhaltet Morgengespinststoffe, indem Ihr Stoff in Ballen webt, während Ihr Euch in der Nähe des Webstuhls des Kreuzzüglers aufhaltet. Kehrt zu Taylor zurück, sobald Ihr genug habt.", progress = "Normalerweise erfordert es einige größere Projekte wie Hemden oder Hosen, um genug Morgengespinststoffe anzusammeln, aber zu Vorführungszwecken sollten einfache Stoffballen genügen.", completion = "Ausgezeichnet! Natürlich ist das nur ein kleiner Teil einer Robe eines Scharlachroten Abtes, aber ich könnte mir vorstellen, dass Ihr von nun an ein besseres Verständnis Eurer eigenen Handwerkskunst habt.\n\nIch nehme Euch die hier ab und bewahre sie auf. Die Vorlage für die heiligen Roben ist ein streng gehütetes Geheimnis, aber ich möchte Euch stattdessen dieses hier geben. Große und robuste Taschen sind heutzutage ein Luxus, aber die Investition lohnt sich. Wer weiß, vielleicht könnt Ihr mit dem Verkauf der Taschen ein gutes Geschäft machen?", sourceObjectiveStatus = "unverified-source-field" }
quests[90120] = { id = 90120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rot ist nicht tot", description = "Hm, apropos Geheimnisse, ich habe an einem neuen Projekt gearbeitet: Luxustaschen für unsere höchstrangigen Soldaten. Sie müssen groß sein, aus der feinsten Seide bestehen und vor allem so rot strahlen wie das Wappen des Scharlachroten Kreuzzugs.\n\nDas Material ist der einfachste Teil, denn ich möchte Eure Morgengespinstfäden dafür benutzen. Doch die perfekte Farbe zu finden, liegt weit außerhalb meiner Fähigkeiten. Sucht in der Welt nach dem perfekten Rotton, dann erkenne ich Euch als Partner in diesem Vorhaben an, indem ich die endgültige Vorlage mit Euch teile.", sourceObjective = "Sammelt eine Vielfalt an Materialien, die als kräftiges, rotes Färbemittel dienen könnten. Roter Farbstoff und rote Rosen können bei Händlern erstanden werden. Feuerblüten könnt Ihr von Kräuterkundlern erhalten. Blut von Helden könnt Ihr in den Pestländern finden. Blutrote Klingenblätter zur Herstellung von Farbstoff könnt Ihr in der Nähe des Mennarsees in Azshara sammeln.", progress = "Lasst Euch ruhig Zeit. Das ist nur ein Leidenschaftsprojekt von mir. Es geht mir viel mehr darum, die passendste rote Farbe zu finden, anstatt die Regale damit zu füllen. Und es wäre mir lieber, wenn Ihr dieselbe Sorgfalt an den Tag legt, anstatt Euch meinetwillen zu beeilen.\n\nIch warte hier.", completion = "Ihr habt ein gutes Auge für Schönheit! Nicht, dass ich je daran gezweifelt hätte, aber ich habe nicht damit gerechnet, dass Ihr sofort einen Rotton findet, der mich so sehr anspricht. Und dann habt Ihr gleich mehrere mitgebracht! \n\n<Taylor bewundert Eure vorgeschlagenen Färbemittel nacheinander, unberührt davon, dass eines davon eine Phiole voll Blut ist.>\n\nDie beiden mit der Bezeichnung \"Blut von Helden\" und \"Blutrotes Klingenblatt\" sind meine Favoriten, das ist eine schwierige Entscheidung. Ich glaube, es ergibt Sinn, wenn wir beide unterschiedliche Farben verwenden. Deshalb nehme ich das Klingenblatt.", sourceObjectiveStatus = "unverified-source-field" }
quests[90510] = { id = 90510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neu-Avalon", description = "Wie Ihr gesehen habt, weist Neu-Avalon eine erhebliche militärische Präsenz auf, bietet Zivilisten aber auch Sicherheit und Schutz.\n\nWenn Ihr eine etwas dauerhaftere Verkleidung zusammenstellen könnt, denkt doch darüber nach, Eure Hilfe anzubieten. Euch bei den Leuten hier beliebt zu machen, könnte unserem Ziel, die Enklave zurückzuerobern, zuträglich sein, ganz zu schweigen von den ganzen Materialien und Ressourcen, derer Ihr Euch dort \"bemächtigen\" könntet. Bereichert Euch selbst und raubt ihrer Kriegsmaschinerie wichtige Vorräte.", sourceObjective = "Nutzt die scharlachrote Insignie, sobald Ihr genug Verkleidungsteile gesammelt habt, um den Scharlachroten Kreuzzug in Neu-Avalon zu täuschen, und sprecht wieder mit Inquisitorin Jociphine. Spielercharaktere mit Handwerksberufen können Rezepte und Vorlagen für scharlachrote Rüstungsteile nutzen, die Ihr von gegnerischen Kreuzzüglern in Tyrs Hand und Neu-Avalon bekommen könnt.", completion = "Überzeugend genug, würde ich sagen.\n\nNeu-Avalon hat vor ein paar Jahren einige seiner Meisterhandwerker an eine Karawane nach Hearthglen verloren, aber wie ich sehe, sind nicht alle ihrer Vorlagen verloren gegangen.\n\nWenn Ihr nicht im Handwerk geübt seid, wird es Euch schwer fallen, in Neu-Avalon voranzukommen. Aber obgleich Ihr wisst, mit einem Hammer oder einer Nadel umzugehen, solltet Ihr zumindest dem Rüstmeister in der Kaserne einen Besuch abstatten. Vielleicht dürft Ihr Euch dort sogar im Lagerraum umsehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[90518] = { id = 90518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Äpfeln und Untoten", description = "Wie schön, Euch wiederzusehen. Ich hatte keine Schwierigkeiten, die Vorratsschränke während Eurer Abwesenheit gefüllt zu halten, doch heute Morgen ist mir aufgefallen, dass ich nicht ganz genug Äpfel habe, um einen Kuchen zu backen. Ich dachte mir, es wäre an der Zeit, mir selbst etwas zu gönnen.\n\nWenn Ihr ein paar Minuten übrig habt, würdet Ihr einen Abstecher zur Plantage machen und einige pflücken? Leider habe ich Johnnys Kuchen auch noch nicht gebacken, aber ohne Äpfel kein Kuchen und ich werde bestimmt keine Äpfel an Johnnys Kuchen verschwenden!\n\nEuch werde ich aber selbstverständlich ein Stück abgeben.", sourceObjective = "Findet die Apfelplantage im Süden von Neu-Avalon und sammelt einige Äpfel. Kehrt zu Carrie Herdfeuer im Gasthaus von Neu-Avalon zurück, wenn Ihr Erfolg hattet. Wenn Ihr die Äpfel für zu teuer haltet, seht Euch nach alternativen Wegen um, sie zu bekommen.", progress = "Denkt daran, dass Johnny Euch seine besten Äpfel vielleicht extra berechnen will, aber Ihr findet bestimmt eine kreative Lösung, wenn Ihr ihm nicht die Taschen füllen wollt.", completion = "Wundervoll, ich werde sofort anfangen! Diese Äpfel sehen sogar noch schöner aus, als die letzte Lieferung von Euch, ich habe fast das Gefühl, Ihr wollt Euch bei mir anbiedern...\n\n<Während Carrie die Arbeitsfläche zum Backen des Kuchens vorbereitet, macht sie eine überschwängliche Geste, mit der sie unmissverständlich ihren Ehering zur Schau stellt.>\n\nDanke, dass Ihr vorbeigekommen seid und unser Abendessen aufgewertet habt. Markus und ich freuen uns schon auf Euren nächsten Besuch!", sourceObjectiveStatus = "unverified-source-field" }
quests[90519] = { id = 90519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fisch auf Abruf", description = "Ich hasse Fisch. Ich kann den Geruch nicht ertragen. Ich finde sie unheimlich. Einfach grässlich.\n\nDa das hier meine Küche ist, kann ich meine Autorität beweisen und NEIN zu Fischimporten sagen, aber manchmal setzen unsere Soldaten sich in den Kopf, sie bräuchten unbedingt ein Fischfestmahl!\n\nHeute ist wieder einer dieser Abende, wie es scheint. Ich brauche Fisch, und zwar schnell!", sourceObjective = "Untersucht das Boot, das südlich von Neu-Avalon angelegt hat, auf die Fischlieferung und bringt Carrie eine Ladung davon.", progress = "Bringt mir bitte keine unvollständige Lieferung. Ich will alles auf einmal hinter mich bringen.\n\nWenn Ihr nicht genug Fisch für den Abend auftreiben könnt, könnt Ihr ja wieder nach Resten suchen. Das wäre sogar vorzuziehen, ehrlich gesagt.", completion = "Ah, ich hatte die Hoffnung, Ihr hättet heute Besseres zu tun, aber Ihr habt es Euch wohl zur Aufgabe gemacht, besonders verlässlich zu werden, seit wir uns kennengelernt haben.\n\nTja. Ich fange wohl besser an.", sourceObjectiveStatus = "unverified-source-field" }
quests[90520] = { id = 90520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lebensmittelsicherheit", description = "Ich erinnere mich, dass eine der ersten Zutaten, die für mich zu sammeln ich Euch bat, Fleisch war. Ich erinnere mich auch an viele Beschwerden an diesem Abend über Übelkeit nach dem Essen. Wirklich außerordentlich seltsam.\n\nAber egal, der Speisekammer fehlt es mal wieder an Fleisch und es wäre schön, wenn jemand Vertrauenswürdiges es auffüllen könnte. Ich kann es mir jetzt nicht leisten, auf eine Lieferung zu warten und dann eine Woche später herauszufinden, dass der Kurier gestorben ist!", sourceObjective = "Besorgt Fleisch, das für Menschen genießbar ist. Wenn Ihr in Neu-Avalon keines findet, könnt Ihr bestimmt (irgendwann) von getöteten Tieren in den Östlichen Pestländern genug erbeuten.", progress = "Wenn Ihr so weiter trödelt, wird es das Abendessen heute verspätet geben.", completion = "Eure Hingabe zur Beständigkeit ist unglaublich, mein Herz. Diese Portionen sind professionell geteilt und besitzen dieselbe Farbe und Textur wie Eure letzte Lieferung. Sollte ich mich je in einer Situation wiederfinden, in der ich mein eigenes Essen erlegen muss, steht Ihr mir dann hoffentlich zur Seite.\n\nUnd Markus natürlich.\n\nLasst mich Euch das abnehmen und anfangen. Neu-Avalon wird heute Abend vorzüglich speisen!", sourceObjectiveStatus = "unverified-source-field" }
quests[90560] = { id = 90560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vertraute Fäule", description = "<Ihr habt eine Phiole mit einer widerlichen, zähen Flüssigkeit auf einem Labortisch gefunden. Sie war umgeben von verschiedenen Zutaten, die sorgfältig abgemessen und in akkurate Portionen geteilt wurden. Obwohl die Kräuter für Euch nicht identifizierbar sind, liegt ein unbeschädigtes und verfärbtes Tierherz in der Nähe.\n\nDie Mischung kommt Euch bekannt vor und erinnert Euch an die jüngeren Experimente der Königlichen Apothekervereinigung. Wenn Eure Neugier Euren Ekel übersteigt, könnte vielleicht eines ihrer Mitglieder Interesse an Eurer Entdeckung zeigen.>", sourceObjective = "Sammelt verfärbte Tierherzen von Kreaturen in den Pestländern und bringt sie und den misslungenen Heiltrank zu einem interessierten Mitglied der Königlichen Apothekervereinigung.", sourceObjectiveStatus = "unverified-source-field" }
quests[90566] = { id = 90566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, meine blutenden Herzen!", description = "Von der beeindruckenden Verderbnis auszugehen, die Eure Proben aufweisen, scheint Ihr Euch in den Pestländern gut auszukennen. Zweifellos versteht Ihr, wie unpraktisch es für ein einsames Mitglied der Königlichen Apothekervereinigung ist, das Bollwerk für Vorräte zu durchqueren.\n\nRenferrel ist an blutenden Herzen interessiert, der Blume. Und dazu an einst schlagenden Herzen. Ich weiß nicht genau, ob es ihm um alchemistische Forschung oder persönliche Vorlieben geht, aber ich bin sicher, er würde sich über eine Lieferung diverser Herzen freuen.", sourceObjective = "Bringt den Korb mit verfärbten Tierherzen und einige blutende Herzen der Pestländer zu Apotheker Renferrel beim Grabmal im Silberwald.", progress = "Ob ich eine Lieferung erwarte?\n\n<Apotheker Renferrel überprüft seine Notizen.>\n\nIhr seht nicht aus wie das Testobjekt, das ich bestellt habe...", completion = "Oh. Meine blutenden Herzen. Nachdem ich monatelang auf Faranell gewartet habe, kommen sie an, als ich die Forschung schon längst aufgegeben habe. Ausgezeichnet.\n\nAber was auch immer Ihr da in diesem Korb habt, weckt mein Interesse. Es erinnert mich an die Herzen der hiesigen Worgen, aber diese hier scheinen mehr Widerstandskraft gegen Fäule und Verderbnis aufzuweisen.\n\nHier, dieses Rezept ist von einer älteren Mischung inspiriert, die ich in der Vergangenheit entwickelt habe. Probiert sie aus und lasst mich wissen, wie es lief.", sourceObjectiveStatus = "unverified-source-field" }
quests[90567] = { id = 90567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unvertraute Fäule", description = "<Ihr habt eine Phiole mit einer widerlichen, zähen Flüssigkeit auf einem Labortisch gefunden. Sie war umgeben von verschiedenen Zutaten, die sorgfältig abgemessen und in akkurate Portionen geteilt wurden. Obwohl die Kräuter für Euch nicht identifizierbar waren, lag ein unbeschädigtes und verfärbtes Tierherz in der Nähe.\n\nAlchemisten in Darnassus könnten eine Idee haben, wie sie die möglicherweise heilenden Eigenschaften dieses Trankes nutzbar machen können. Ihr solltet ihnen außerdem Blumen mitbringen. Es wäre unhöflich, mit nur einem Haufen Herzen in ein Geschäft zu platzen.>", sourceObjective = "Sammelt verfärbte Tierherzen und blutende Herzen in den Pestländern. Bringt sie und den misslungenen Heiltrank zu einem interessierten Alchimisten in Darnassus.", progress = "Ishnu-alah, Reisender. Seid Ihr gekommen, um die Kunst der Alchemie zu studieren, oder womit kann ich Euch sonst helfen?", completion = "Das hatte ich fast vermutet. Kaum zu glauben, aber Ihr seid nicht die erste Person, die mir exakt diese Enthüllung vorlegt. Wären die Umstände nicht so finster, würde ich alles für einen ausgefeilten Scherz auf meine Kosten halten.\n\nDie Effekte der Pestländer zu studieren ist zwar interessant, aufgrund der großen Entfernung aber nicht immer machbar. Dennoch konnte ich mit Proben, die mir vor einer Weile überreicht wurden, schon Fortschritte machen und würde meine Erkenntnisse gerne mit Euch teilen.\n\nDenkt bitte an mich, wenn Ihr weitere Exemplare findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[90625] = { id = 90625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf unheilvollen Flügeln", description = "Ein zerrissener Flügel des Schreckenslords Balnazzar ist alles, was von dem gestürzten Nathrezim übrig geblieben ist.\n\nJemand in der Kapelle des hoffnungsvollen Lichts könnte daran interessiert sein.", sourceObjective = "Bringt den Flügel Balnazzars zur Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[90626] = { id = 90626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sehne des Lichts", description = "Grok'lo wird Treffen mit seinem speziellen Handwerker arrangieren, sobald Ihr geeignete Sehne für Flügel von Riesenfledermaus gefunden habt.\n\nGrok'lo empfiehlt, bestmögliche Sehne zu finden.\n\n<Grok'lo lächelt unter seinem Helm.>\n\nDrachensehnen definitiv am Besten.", sourceObjective = "Besiegt Solistrasza und erlangt eine Sehne eines ausgewachsenen Lichtdrachen. Dann bringt sie zu Grok'lo in die Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[90627] = { id = 90627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gewiefte Handwerker", description = "In Ordnung, Name meines Handwerkers ist Mizzle der Gewiefte.\n\nIst so offensichtlich, selbst Grok'lo kann sehen! Aber alle denken, Name ist, weil er clever ist. NEIN! Ist Oger, ist alles andere als clever! Ist einfach nur gewieft beim Handwerken!\n\n<Grok'lo nickt.>\n\nGeht in Norden von Düsterbruch und trefft ihn. Aber stellt sicher, dass er nicht abgelenkt ist, wenn Ihr ihn seht.\n\nUnd geht alleine.", sourceObjective = "Trefft Mizzle den Gewieften im Norden von Düsterbruch.\n\nStellt sicher, dass er nicht abgelenkt ist, also keine wichtigen Oger auf dem Weg töten, sonst er muss sie ersetzen und kann Euch nicht helfen.\n\nUnd geht alleine.", sourceObjectiveStatus = "unverified-source-field" }
